\label{def:cts}
A \emph{computable topological space} is a pair $(X,(B_i)_{i\in\mathbb{N}})$, where $X$ is a $T_0$ topological space, $(B_i)_{i\in \mathbb{N}}$ is a numbered basis for its topology, and for which there is a c.e.\ relation $\operatorname{Incl}\subseteq\mathbb{N}^3$ which is both:
\begin{itemize}
\item \emph{sound}: $(i,j,k)\in\operatorname{Incl}$ implies $B_k\subseteq B_i\cap B_j$; and
\item \emph{rich}: whenever $x\in B_i\cap B_j$, there is $k$ with $x\in B_k$ and $(i,j,k)\in\operatorname{Incl}$.
\end{itemize}

\label{lem:image}
Suppose that $X$ and $Y$ are computable topological spaces and $f:X\to Y$ is computable and surjective.
\begin{enumerate}
    \item If $X$ is computably compact, then so is $Y$.
    \item If $X$ is computably overt, then so is $Y$.
\end{enumerate}

\label{lem:quotient}
Let $X$ be computably compact and $\sim$ an effectively closed equivalence relation on $X$ for which $Y:=X/\sim$ is $T_0$. Then the following hold:
\begin{enumerate}
    \item $(C_A)_{A\ \mathrm{finite}}$ is a numbered basis making $Y$ a computable topological space.
    \item The canonical projection $\pi:X\to Y$ is computable.
    \item $Y$ is computably compact.
    \item If $X$ is computably overt, so is $Y$.
\end{enumerate}

\label{lem:basis}
The following facts hold:
\begin{enumerate}
    \item $B_{n,F}=(U_F)^\ast$, where $U_F:=\{\alpha\in P : \alpha(n)\in F\}$.
    \item Each $B_{n,F}$ is open.
    \item The family $(B_{n,F})$ is cofinal among the sets $C_A$ of Lemma~\ref{lem:quotient}, and is therefore a basis for $\partial G$.  
    \item If $\alpha\in P$ and $\pi(\alpha)=\xi$, then setting $F:=B(\alpha(n),2\delta)\cap P_n$, we have $\xi\in B_{n,F}$.
\end{enumerate}

\label{lem:small}
For each $n\in \mathbb{N}$ and each pair $a<b$ of rational numbers, let $W_{n,a,b}$ be a c.e.\ index set with $\bigcup_{i\in W_{n,a,b}}B_i=f_n^{-1}(a,b)$, closed under refinement in the sense that $i'\le^\ast i\in W_{n,a,b}$ implies $i'\in W_{n,a,b}$. Let $\mathrm{Small}(k)$ denote the set of $i\in \mathbb{N}$ such that, for each $n\leq k$, there are rational numbers $a_n<b_n$ such that $b_n-a_n<2^{-k}$ and $i\in W_{n,a_n,b_n}$.
Then:
\begin{itemize}
    \item $\mathrm{Small}(k)$ is c.e.\ and closed under refinement.
    \item If $i\in\mathrm{Small}(k)$, then $\operatorname{diam}_\rho(\overline{B_i})\le2^{-k+2}$.
    \item For every $x\in X$, there is $i\in\mathrm{Small}(k)$ with $x\in B_i$.
\end{itemize}
